function a(t){if(t==null)return"";const n=Math.floor(t/60),r=t%60;return n>0?`${n}h${r.toString().padStart(2,"0")}`:`${r}'`}function l(t){const{velo_km:n,velo_dplus:r}=t,o=typeof n=="string"?parseFloat(n):n,e=typeof r=="string"?parseInt(r,10):r,u=o/20+e/500;return Math.round(u*60)}function s(t){const[n,r]=[t.km,t.dplus].map(o=>o==null||o===""?NaN:Number(o));return Number.isNaN(n)||Number.isNaN(r)?null:Math.round((n/4+r/500)*60)}export{s as a,l as c,a as f};
